<template><div><div class="dashboard-cards"><el-card v-for="item in cards" :key="item.label" shadow="hover" @click="item.route&&$router.push(item.route)"><small>{{item.label}}</small><b :class="item.type">{{item.value}}</b><span>{{item.help}}</span></el-card></div><el-row :gutter="16"><el-col :xs="24" :md="12"><el-card><template #header>本月财务</template><div class="finance"><div><small>收入</small><b class="income">¥{{money(data?.monthIncome)}}</b></div><div><small>支出</small><b class="expense">¥{{money(data?.monthExpense)}}</b></div><div><small>结余</small><b>¥{{money((data?.monthIncome||0)-(data?.monthExpense||0))}}</b></div></div></el-card></el-col><el-col :xs="24" :md="12"><el-card><template #header>今日建议</template><el-alert v-if="data?.overdueTaskCount" :title="`有 ${data.overdueTaskCount} 项任务已逾期，建议先完成或重新安排。`" type="warning" :closable="false"/><el-alert v-else-if="data?.pendingInboxCount" :title="`收件箱还有 ${data.pendingInboxCount} 条待确认记录。`" type="info" :closable="false"/><el-empty v-else description="当前没有紧急待处理项" :image-size="60"/></el-card></el-col></el-row></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{getDailyDashboard,type DailyDashboard}from'@/api/productivity';const data=ref<DailyDashboard>();const cards=computed(()=>[{label:'今日任务',value:data.value?.todayTaskCount||0,help:'计划在今天完成',route:'/life',type:''},{label:'逾期任务',value:data.value?.overdueTaskCount||0,help:'需要重新安排',route:'/work',type:'warning'},{label:'待触发提醒',value:data.value?.pendingReminderCount||0,help:'提醒中心',route:'/reminders',type:''},{label:'待确认收件箱',value:data.value?.pendingInboxCount||0,help:'建议分类后确认',route:'/inbox',type:'warning'},{label:'待确认账单',value:data.value?.unconfirmedTransactionCount||0,help:'补充消费分类',route:'/finance',type:'warning'},{label:'近 7 日开发记录',value:data.value?.recentDevLogCount||0,help:'开发沉淀',route:'/devlogs',type:''},{label:'进行中学习计划',value:data.value?.activeLearningCount||0,help:'保持成长节奏',route:'/learning/plans',type:''},{label:'资金流显著变化',value:data.value?.fundFlowAlertCount||0,help:'仅作行情指标参考',route:'/stocks',type:'warning'}]);const money=(value?:number)=>Number(value||0).toFixed(2);onMounted(async()=>{data.value=(await getDailyDashboard()).data;});</script>
<style scoped>.dashboard-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:16px}.dashboard-cards .el-card{cursor:pointer}.dashboard-cards small,.dashboard-cards span{display:block;color:#64748b}.dashboard-cards b{display:block;font-size:28px;margin:10px 0}.warning{color:#ea580c}.finance{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.finance small,.finance b{display:block}.finance b{font-size:20px;margin-top:8px}.income{color:#16a34a}.expense{color:#dc2626}@media(max-width:900px){.dashboard-cards{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.dashboard-cards{grid-template-columns:1fr}.finance{grid-template-columns:1fr}}</style>
